function parseDuration(s) {
    /**
     * Parse a duration string like '1d2h', '1h30m', '45s' or '2h5s' into total seconds.
     *
     * Accepts days (d), hours (h), minutes (m) and seconds (s) in any order, e.g.
     * '1d2h', '1h30m', '45s', '2h5s', '90m'. Case-insensitive; no spaces allowed.
     *
     * Returns the total as an integer. Throws an Error if the string is empty or
     * contains anything that isn't a recognised unit.
     */
    if (!s) {
        throw new Error("empty duration string");
    }

    const units = { d: 86400, h: 3600, m: 60, s: 1 };
    let total = 0;
    let matched = false;

    for (const match of s.toLowerCase().matchAll(/(\d+)([a-z]+)/g)) {
        matched = true;
        const [, value, unit] = match;
        if (!(unit in units)) {
            throw new Error(`unknown unit '${unit}' in '${s}'`);
        }
        total += parseInt(value, 10) * units[unit];
    }

    // Reject strings with stray characters (e.g. '1x30m') even though they
    // contain valid parts.
    if (!matched || s.toLowerCase().replace(/\d+[a-z]+/g, "") !== "") {
        throw new Error(`invalid duration string '${s}'`);
    }

    return total;
}
