function parseDuration(s) {
    /**
     * Parse a duration string like '1d2h', '1h30m', '45s' into total seconds.
     *
     * Accepts days (d), hours (h), minutes (m) and seconds (s) in any combination,
     * e.g. '1d2h' -> 93600, '1h30m' -> 5400, '45s' -> 45, '2h5s' -> 7205.
     * Case-insensitive.
     *
     * @param {string} s - The duration string to parse.
     * @returns {number} The total number of seconds.
     * @throws {Error} If the input is not a string or contains invalid units/format.
     */
    if (typeof s !== 'string') {
        throw new Error(`Expected a string, got ${typeof s}`);
    }

    const lower = s.trim().toLowerCase();
    const pattern = /^(?:\d+d)?(?:\d+h)?(?:\d+m)?(?:\d+s)?$/;
    if (!pattern.test(lower)) {
        throw new Error(`Invalid duration format: '${s}'`);
    }

    let total = 0;
    const matches = lower.matchAll(/(\d+)([dhms])/g);
    for (const [, value, unit] of matches) {
        const num = parseInt(value, 10);
        switch (unit) {
            case 'd':
                total += num * 86400;
                break;
            case 'h':
                total += num * 3600;
                break;
            case 'm':
                total += num * 60;
                break;
            case 's':
                total += num;
                break;
        }
    }
    return total;
}
